import React from 'react';
import TestRenderer, { act } from 'react-test-renderer';

import SVGRowWaitingComponent from '../src/assets/svg/row-waiting';
import { APP_PAGE_BACKGROUND_COLOR } from '../src/style/theme/theme-common';

jest.mock('react-native-svg', () => ({
  __esModule: true,
  default: 'MockSvg',
  Path: 'MockPath',
}));

describe('SVGRowWaitingComponent', () => {
  test('fills every figure with the shared page background color', () => {
    let renderer: TestRenderer.ReactTestRenderer;

    act(() => {
      renderer = TestRenderer.create(
        <SVGRowWaitingComponent height={28} width={28} />
      );
    });

    const paths = renderer!.root.findAllByType('MockPath' as unknown as React.ElementType);

    expect(APP_PAGE_BACKGROUND_COLOR).toBe('#f2f5f4');
    expect(paths.length).toBeGreaterThan(0);
    paths.forEach((path) => {
      expect(path.props.fill).toBe(APP_PAGE_BACKGROUND_COLOR);
      expect(path.props.fill).not.toBe('#CE0058');
    });
  });
});

import React from 'react';
import TestRenderer, { act } from 'react-test-renderer';

import SVGRowWaitingComponent from '../src/assets/svg/row-waiting';
import { APP_THEME_COLOR } from '../src/style/theme/theme-common';

jest.mock('react-native-svg', () => ({
  __esModule: true,
  default: 'MockSvg',
  Path: 'MockPath',
}));

describe('SVGRowWaitingComponent', () => {
  test('fills every figure with the shared theme color', () => {
    let renderer: TestRenderer.ReactTestRenderer;

    act(() => {
      renderer = TestRenderer.create(
        <SVGRowWaitingComponent height={28} width={28} />
      );
    });

    const paths = renderer!.root.findAllByType('MockPath');

    expect(APP_THEME_COLOR).toBe('#137963');
    expect(paths.length).toBeGreaterThan(0);
    paths.forEach((path) => {
      expect(path.props.fill).toBe(APP_THEME_COLOR);
      expect(path.props.fill).not.toBe('#CE0058');
      expect(path.props.fill).not.toBe('#f2f5f4');
    });
  });
});
